<?php declare(strict_types=1); namespace Annam; $title=$order['order_no']; ?>
<p><a href="/manage/orders/">← Orders</a></p><div class="php-cart-grid"><section class="o-card"><h2><?= e($order['address']['recipient_name']??$customer['name']) ?></h2><p><?= e($order['address']['phone']??$customer['phone']) ?></p><p><?= e(implode(', ',array_filter(array_intersect_key($order['address'],array_flip(['line1','line2','landmark','city','pincode','fulfilment']))))) ?></p><p><?= e($order['channel'].' · '.$order['fulfilment'].' · '.($order['delivery_date']??'')) ?></p><?php foreach($order['items'] as $line): ?><p class="php-total"><span><?= e($line['quantity'].' × '.$line['name']) ?></span><b><?= money($line['line_total']) ?></b></p><?php endforeach; ?><p class="php-total">Delivery <b><?= money($order['delivery_fee']) ?></b></p><h2 class="php-total">Total <b><?= money($order['total']) ?></b></h2><p>Payment: <strong><?= e($order['payment_status']) ?></strong><?php if($intent): ?> · Razorpay <?= e($intent['mode']) ?> · <?= e($intent['state']) ?><?php endif; ?></p><?php if($intent['bill_error']??''): ?><p class="php-error"><?= e($intent['bill_error']) ?></p><?php endif; ?>
<?php if($invoice): ?><a class="o-btn o-btn-primary" href="/manage/bills/<?= e($invoice['id']) ?>/">View / print bill</a><?php elseif($order['payment_status']==='paid'): ?><form method="post" action="bill/"><?= csrf() ?><button class="o-btn">Issue bill</button></form><?php endif; ?>
<?php if($intent): ?><form method="post" action="reconcile/"><?= csrf() ?><button class="o-btn">Verify with Razorpay</button></form><?php if($intent['state']==='captured'): ?><form method="post" action="refund/" class="o-form"><?= csrf() ?><label class="o-field">Full refund reason<input name="reason" required maxlength="200"></label><button class="o-btn">Request full refund</button></form><?php endif; ?>
<?php elseif(!in_array($order['payment_status'],['paid','refunded'],true)&&$order['status']!=='cancelled'): ?><form method="post" action="confirm/" class="o-form"><?= csrf() ?><label class="o-field">Payment reference<input name="reference" maxlength="120"></label><label class="php-switch-row"><input type="checkbox" class="php-toggle" role="switch" name="received" value="1" required><span>I confirm the payment was received</span></label><button class="o-btn o-btn-primary">Confirm payment</button></form><?php endif; ?></section>
<section class="o-card"><h2><?= e(ucfirst(str_replace('_',' ',$order['status']))) ?></h2><?php if(!in_array($order['status'],['cancelled','delivered'],true)): ?><form method="post" action="status/" class="o-form"><?= csrf() ?><label class="o-field">Next step<select name="status"><?php foreach([...(Orders::FLOW[$order['status']]??[]),'cancelled'] as $status): ?><option value="<?= e($status) ?>"><?= e(ucfirst(str_replace('_',' ',$status))) ?></option><?php endforeach; ?></select></label><label class="o-field">Note / cancellation reason<input name="note" maxlength="200"></label><label class="o-field">Rider name<input name="rider_name" maxlength="120"></label><label class="o-field">Rider phone<input name="rider_phone" maxlength="20"></label><button class="o-btn o-btn-primary">Update order</button></form><?php endif; ?><h3>Order history</h3><?php foreach($events as $event): ?><p><strong><?= e(str_replace('_',' ',$event['to_status'])) ?></strong> · <?= e($event['actor']) ?><small><?= e($event['at']) ?> — <?= e($event['note']) ?></small></p><?php endforeach; ?></section></div>
